dt=.05; prev=now[7:10]; est=0
for row in commands:
 d=float(np.linalg.norm(row[:3]-prev)); est+=max(1,int(np.ceil(d/(.25*dt)))+(1 if d>.25*dt else 0)); prev=row[:3]
